        return
    end
    print(((("[AutoChessMode] 为玩家 " .. tostring(playerId)) .. " 创建敌人，使用关卡") .. tostring(stageId)) .. "配置")
    print("[AutoChessMode] 关卡类型: " .. stageConfig.primaryNodeType)
